using System;using System.IO;using System.Linq;using System.Collections.Generic;using Cysharp.Threading.Tasks;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using SushiAndFish.Casino;using SushiAndFish.Casino.Original;using SushiAndFish.Casino.Original.Extensions;using Object=UnityEngine.Object;
public static partial class CityExpansionPlayAudit {
 [Serializable]public class EnvironmentReceipt{public string utc,pipeline,colorSpace;public int quality;public List<string> volumes=new List<string>(),lights=new List<string>(),stacks=new List<string>();}
 public static void EnvironmentAndCoast(){SessionState.SetBool(Key+"environmentCompare",true);SessionState.SetBool(Key+"coastAndDice",false);SessionState.SetBool(Key+"crapsOnly",false);SessionState.SetBool(Key+"environment",true);RoofsAndCoast();}
 static bool CasinoOwned(Transform t,ParkCasinoIntegration c){if(t.IsChildOf(c.ModuleRoot))return true;var local=MonoSingleton<LocalManager>.Instance;if(local&&t.IsChildOf(local.transform))return true;var game=NetworkSingleton<GameManager>.Instance;if(game&&t.IsChildOf(game.transform.root))return true;if(c.Bootstrap.HostSupportInstance&&t.IsChildOf(c.Bootstrap.HostSupportInstance.transform))return true;return false;}
 static string VolumeValues(VolumeProfile p){if(!p)return "null";string s=p.name;if(p.TryGet<ColorAdjustments>(out var color))s+=" exposure="+color.postExposure.value+" override="+color.postExposure.overrideState+" color="+color.colorFilter.value+" sat="+color.saturation.value+" contrast="+color.contrast.value;if(p.TryGet<Bloom>(out var bloom))s+=" bloom="+bloom.intensity.value+" threshold="+bloom.threshold.value;if(p.TryGet<Tonemapping>(out var tone))s+=" tonemap="+tone.mode.value;return s;}
 static string StackValues(){var s=VolumeManager.instance.stack;return "exposure="+s.GetComponent<ColorAdjustments>()?.postExposure.value+" bloom="+s.GetComponent<Bloom>()?.intensity.value+" tone="+s.GetComponent<Tonemapping>()?.mode.value;}
 static async UniTask EnvironmentInspection(ParkCasinoIntegration c){
  var q=new EnvironmentReceipt{utc=DateTime.UtcNow.ToString("o"),pipeline=UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline?.name,colorSpace=QualitySettings.activeColorSpace.ToString(),quality=QualitySettings.GetQualityLevel()};
  foreach(var v in Object.FindObjectsByType<Volume>(FindObjectsInactive.Include,FindObjectsSortMode.None))q.volumes.Add(FullPath(v.transform)+" scene="+v.gameObject.scene.name+" active="+v.isActiveAndEnabled+" owned="+CasinoOwned(v.transform,c)+" global="+v.isGlobal+" weight="+v.weight+" priority="+v.priority+" profile="+VolumeValues(v.profile));
  foreach(var l in Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(l=>l.isActiveAndEnabled))q.lights.Add(FullPath(l.transform)+" owned="+CasinoOwned(l.transform,c)+" type="+l.type+" intensity="+l.intensity+" color="+l.color+" pos="+l.transform.position);
  c.HostPlayer.TeleportPlayer(new Vector3(105.5f,3.1f,-63),true);c.HostPlayer.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.4f);await Aim(c,new Vector3(88,8,-52.5f));await Snapshot("casino-lighting-baseline.png");q.stacks.Add("baseline "+StackValues());
  if(!SessionState.GetBool(Key+"environmentCompare",true)){File.WriteAllText(Path.Combine(Reports,"casino-environment-final.json"),JsonUtility.ToJson(q,true));return;}
  var vs=Object.FindObjectsByType<Volume>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(v=>CasinoOwned(v.transform,c)).ToArray();var states=vs.Select(v=>v.enabled).ToArray();var ls=Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(l=>CasinoOwned(l.transform,c)).ToArray();var lightStates=ls.Select(l=>l.enabled).ToArray();foreach(var v in vs)v.enabled=false;foreach(var l in ls)l.enabled=false;await Pause(.2f);await Snapshot("casino-lighting-owned-environment-disabled.png");q.stacks.Add("ownedDisabled "+StackValues());
  var cameras=c.HostPlayer.GetComponentsInChildren<Camera>(true).Append(CasinoRuntimeContext.PlayerCamera).Distinct().Select(cam=>cam.GetComponent<UniversalAdditionalCameraData>()).Where(d=>d).ToArray();var post=cameras.Select(d=>d.renderPostProcessing).ToArray();foreach(var d in cameras)d.renderPostProcessing=false;await Pause(.2f);await Snapshot("casino-lighting-no-post.png");q.stacks.Add("noPost "+StackValues());for(int i=0;i<cameras.Length;i++)cameras[i].renderPostProcessing=post[i];
  for(int i=0;i<vs.Length;i++)vs[i].enabled=states[i];for(int i=0;i<ls.Length;i++)ls[i].enabled=lightStates[i];File.WriteAllText(Path.Combine(Reports,"casino-environment-diagnosis.json"),JsonUtility.ToJson(q,true));
 }
}
